$(function(){var i3StartProject=function(ele){this.element=$(ele);this.form_container=this.element.find('#i3-sp-contactform');this.project_category_element=this.element.find('input[name=project_category]');this.project_sub_category_element=this.element.find('input[name="project_sub_category[]"]');this.project_category_field=this.element.find('input[name=project_category_field]');this.project_sub_category_field=this.element.find('input[name=project_sub_category_field]');this.start_project_toggle=$('.i3-start-project-toggle');this.binds()}
i3StartProject.prototype.binds=function(){var self=this;self.start_project_toggle.on('click',function(ev){ev.preventDefault();$('body').toggleClass('--show-start-project')});self.project_category_element.on('change',function(ele){self.resetProjectSubCategories();if($(this).is(':checked')){self.showProjectSubCategories($(this).data('project-category'));self.project_category_field.val($(this).val())}});self.project_sub_category_element.on('change',function(ele){var checked=self.project_sub_category_element.filter(':checked');var checked_values='';if(checked.length){self.form_container.show();checked.each(function(index,ele){checked_values+=$(this).val()+','});console.log(checked_values)}else{self.form_container.hide();checked_values=''}
self.project_sub_category_field.val(checked_values)})}
i3StartProject.prototype.showProjectSubCategories=function(id){var self=this;self.element.find('.i3-project-sub-category').hide();self.element.find('#'+id).show()}
i3StartProject.prototype.resetProjectSubCategories=function(id){var self=this;self.project_sub_category_element.prop('checked',!1).trigger('change')}
new i3StartProject($('#i3-sp'))})